import pandas as pd
import json
import pdfplumber

# Extract data from PDF
pdf_employees = {}
print("Extracting data from PDF...")

with pdfplumber.open("/root/employees_backup.pdf") as pdf:
    for page in pdf.pages:
        tables = page.extract_tables()
        for table in tables:
            if table and len(table) > 1:
                # First row should be headers
                headers = table[0]
                print(f"PDF Headers: {headers}")

                # Process data rows
                for row in table[1:]:
                    if row and len(row) >= 5:
                        # Assuming columns are: ID, Name, Department, Salary, Years, Score
                        emp_id = str(row[0]).strip() if row[0] else ""
                        if emp_id and emp_id.startswith("EMP"):
                            employee = {
                                "Name": str(row[1]).strip() if row[1] else "",
                                "Department": str(row[2]).strip() if row[2] else "",
                                "Salary": float(row[3]) if row[3] and str(row[3]).replace('.','').isdigit() else row[3],
                                "Years": float(row[4]) if row[4] and str(row[4]).replace('.','').isdigit() else row[4],
                                "Score": float(row[5]) if row[5] and str(row[5]).replace('.','').isdigit() else row[5]
                            }
                            pdf_employees[emp_id] = employee

